# --- Custom CUDA kernel for batch normalization (mean, var) ---
batchnorm2d_cuda_source = """
#include <torch/extension.h>
#include <cmath>

torch::Tensor batchnorm2d_cuda(torch::Tensor x, const torch::Tensor gamma, const torch::Tensor beta) {
    auto eps = 1e-5;
    // Compute mean over dim=0 (batch)
    auto mean = x.mean(dim=0, keepdim=True);
    // Compute variance over dim=0
    auto var = x.var(dim=0, keepdim=True) + eps;
    // Normalize
    auto out = (x - mean) / sqrt(var);
    return out.mul(gamma) + beta;
}
"""

batchnorm2d_cuda = load_inline(
    name="batchnorm2d_cuda",
    cpp_sources=batchnorm2d_cuda_source,
    cuda_sources="",  # no extra kernels needed as we rely on torch ops inside
    functions=["batchnorm2d_cuda"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, num_features: int):
        super().__init__()
        self.num_features = num_features
        # Initialize gamma and beta as learnable parameters (same shape as features)
        self.gamma = nn.Parameter(torch.ones(num_features))
        self.beta = nn.Parameter(torch.zeros(num_features))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Args:
            x: Input tensor of shape (batch_size, num_features, dim1, dim2)
        Returns:
            Output tensor after BatchNorm2d applied.
        """
        return batchnorm2d_cuda(x, self.gamma.to(x.device), self.beta.to(x.device))

